import React, { useState, useEffect } from 'react';



import { Link } from 'react-router-dom';



import { getFeaturedProducts, getProductCategories, createSubscription } from '../services/api';



import { isAuthenticated } from '../util/auth';



import ProductCard from '../components/ProductCard';



import Toast from '../components/Toast';



import { useTheme } from '../context/ThemeContext';



import useToast from '../hooks/useToast';







const Home = () => {



  const [featuredProducts, setFeaturedProducts] = useState([]);



  const [categories, setCategories] = useState([]);



  const [loading, setLoading] = useState(true);



  const [currentSlide, setCurrentSlide] = useState(0);



  const [featureSlide, setFeatureSlide] = useState(0);



  const [showScrollTop, setShowScrollTop] = useState(false);



  const [featuredSlide, setFeaturedSlide] = useState(0);



  const [selectedPlan, setSelectedPlan] = useState(null);



  const [subscriptionModal, setSubscriptionModal] = useState(false);



  const [loadingSubscription, setLoadingSubscription] = useState(false);



  const [chatPopup, setChatPopup] = useState(false);



  const [selectedCategory, setSelectedCategory] = useState('all');



  const [viewMode, setViewMode] = useState('grid');



  const { isDarkMode } = useTheme();



  const { toasts, removeToast } = useToast();







  useEffect(() => {



    fetchData();



    // Handle scroll events

    const handleScroll = () => {

      setShowScrollTop(window.scrollY > 50);

    };



    window.addEventListener('scroll', handleScroll);



    



    // Auto-rotate hero slides



    const heroInterval = setInterval(() => {



      setCurrentSlide((prev) => (prev + 1) % 3);



    }, 4000);



    



    // Auto-rotate feature slides



    const featureInterval = setInterval(() => {



      setFeatureSlide((prev) => (prev + 1) % 3);



    }, 3000);



    



    return () => {



      clearInterval(heroInterval);



      clearInterval(featureInterval);



      window.removeEventListener('scroll', handleScroll);



    };



  }, []);







  const fetchData = async () => {



    try {



      setLoading(true);



      const [featuredRes, categoriesRes] = await Promise.all([



        getFeaturedProducts(),



        getProductCategories()



      ]);



      setFeaturedProducts(featuredRes.data);



      setCategories(categoriesRes.data);



    } catch (error) {



      console.error('Error fetching data:', error);



    } finally {



      setLoading(false);



    }



  };



  const scrollToTop = () => {



    window.scrollTo({



      top: 0,



      behavior: 'smooth'



    });



  };







  const handleSubscribe = async (planType) => {



    if (!userAuthenticated) {



      // Redirect to login if not authenticated



      window.location.href = '/login';



      return;



    }



    setSelectedPlan(planType);



    setSubscriptionModal(true);



  };







  const createSubscriptionHandler = async () => {



    if (!selectedPlan) return;



    



    try {



      setLoadingSubscription(true);



      



      const subscriptionData = {



        planType: selectedPlan,



        startDate: new Date().toISOString(),



        status: 'active'



      };



      



      const response = await createSubscription(subscriptionData);



      



      if (response.status === 201 || response.status === 200) {



        // Success - show success message



        alert('Subscription created successfully!');



        setSubscriptionModal(false);



        setSelectedPlan(null);



      } else {



        // Error - show error message



        alert(response.data?.message || 'Failed to create subscription');



      }



    } catch (error) {



      console.error('Subscription error:', error);



      alert('An error occurred while creating subscription');



    } finally {



      setLoadingSubscription(false);



    }



  };







  const getPlanDetails = (planType) => {



    const plans = {



      daily: {



        name: 'Daily Plan',



        price: 29,



        duration: 'day',



        features: [



          '500ml Fresh Milk Daily',



          '6:00 AM - 7:00 AM Delivery',



          'Pause Anytime',



          'Free Delivery'



        ]



      },



      weekly: {



        name: 'Weekly Plan',



        price: 189,



        duration: 'week',



        features: [



          '3.5L Milk Per Week',



          'Flexible Delivery Days',



          '10% Discount',



          'Free Delivery'



        ]



      },



      monthly: {



        name: 'Monthly Plan',



        price: 799,



        duration: 'month',



        features: [



          '15L Milk Per Month',



          'Custom Schedule',



          '20% Discount',



          'Free Delivery + Priority'



        ]



      }



    };



    



    return plans[planType] || null;



  };







  const userAuthenticated = isAuthenticated();







  return (



    <>

      <div className="fade-in">

      {/* Professional Corporate Hero Section */}
      <section className="relative min-h-screen flex">
        {/* Left Side - Content */}
        <div className={`w-full lg:w-1/2 flex items-center justify-center px-8 lg:px-16 relative overflow-hidden ${isDarkMode ? 'bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900' : 'bg-gradient-to-br from-slate-50 via-gray-100 to-slate-50'}`}>
          {/* Subtle Background Animation */}
          <div className="absolute inset-0 opacity-30">
            <div className={`absolute top-0 left-0 w-64 h-64 rounded-full blur-3xl ${isDarkMode ? 'bg-blue-600' : 'bg-blue-400'} animate-pulse`}></div>
            <div className={`absolute bottom-0 right-0 w-64 h-64 rounded-full blur-3xl ${isDarkMode ? 'bg-purple-600' : 'bg-purple-400'} animate-pulse animation-delay-2000`}></div>
          </div>
          
          <div className="max-w-2xl space-y-8 relative z-10">
            {/* Modern Company Badge */}
            <div className={`inline-flex items-center px-6 py-3 rounded-full backdrop-blur-lg border shadow-lg ${isDarkMode ? 'bg-gray-800/50 border-gray-700' : 'bg-white/70 border-gray-200'}`}>
              <span className="w-3 h-3 bg-gradient-to-r from-green-400 to-emerald-500 rounded-full mr-3 animate-pulse shadow-lg shadow-green-400/50"></span>
              <span className={`text-sm font-semibold ${isDarkMode ? 'text-gray-200' : 'text-gray-700'}`}>Est. 2020 • Trusted by 10K+ Families</span>
            </div>

            {/* Enhanced Main Heading */}
            <div className="space-y-6">
              <h1 className={`text-5xl lg:text-7xl font-black leading-tight ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                <span className="block">Premium Dairy</span>
                <span className="block bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">Delivered Daily</span>
              </h1>
              
              <p className={`text-xl leading-relaxed ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} font-light`}>
                Experience the finest quality dairy products from local farms. 
                <span className="block mt-2 font-semibold bg-gradient-to-r from-blue-500 to-purple-500 bg-clip-text text-transparent">
                  Fresh milk, artisanal cheese, and premium butter delivered to your doorstep.
                </span>
              </p>
            </div>

            {/* Enhanced Key Features */}
            <div className="grid grid-cols-2 gap-6">
              {[
                { icon: '🌱', title: '100% Natural', desc: 'No preservatives', color: 'blue' },
                { icon: '🚚', title: 'Daily Delivery', desc: '6 AM - 9 AM', color: 'green' },
                { icon: '🏆', title: 'Premium Quality', desc: 'Lab tested', color: 'purple' },
                { icon: '🏡', title: 'Local Farms', desc: 'Direct sourcing', color: 'orange' }
              ].map((feature, index) => (
                <div key={index} className={`group flex items-center space-x-4 p-4 rounded-2xl backdrop-blur-lg border transition-all duration-300 hover:scale-105 ${isDarkMode ? 'bg-gray-800/30 border-gray-700 hover:bg-gray-800/50' : 'bg-white/50 border-gray-200 hover:bg-white/70'}`}>
                  <div className={`w-12 h-12 bg-gradient-to-br from-${feature.color}-100 to-${feature.color}-200 dark:from-${feature.color}-900 dark:to-${feature.color}-800 rounded-xl flex items-center justify-center shadow-lg group-hover:shadow-xl transition-shadow duration-300`}>
                    <span className="text-2xl">{feature.icon}</span>
                  </div>
                  <div>
                    <h3 className={`font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>{feature.title}</h3>
                    <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>{feature.desc}</p>
                  </div>
                </div>
              ))}
            </div>

            {/* Enhanced CTA Buttons */}
            <div className="flex flex-col sm:flex-row gap-4 pt-6">
              <Link 
                to="/products" 
                className="group relative px-10 py-5 bg-gradient-to-r from-blue-600 to-purple-600 text-white font-bold rounded-2xl hover:from-blue-700 hover:to-purple-700 transform hover:scale-105 transition-all duration-300 shadow-xl hover:shadow-2xl"
              >
                <span className="relative z-10 flex items-center justify-center gap-3">
                  Start Shopping
                  <svg className="w-5 h-5 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                  </svg>
                </span>
                <div className="absolute inset-0 bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl blur opacity-75 group-hover:opacity-100 transition duration-300"></div>
              </Link>
              
              {!userAuthenticated && (
                <Link 
                  to="/register" 
                  className={`px-10 py-5 backdrop-blur-lg font-bold rounded-2xl border-2 transform hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl ${isDarkMode ? 'bg-gray-800/50 border-gray-600 text-gray-200 hover:bg-gray-800/70 hover:border-gray-500' : 'bg-white/70 border-gray-300 text-gray-700 hover:bg-white/90 hover:border-gray-400'}`}
                >
                  Create Free Account
                </Link>
              )}
            </div>

            {/* Enhanced Trust Indicators */}
            <div className={`flex items-center justify-center space-x-12 pt-8 border-t backdrop-blur-lg ${isDarkMode ? 'border-gray-700' : 'border-gray-200'}`}>
              {[
                { number: '10K+', label: 'Happy Customers' },
                { number: '50+', label: 'Products' },
                { number: '4.9★', label: 'Rating' }
              ].map((stat, index) => (
                <div key={index} className="text-center group">
                  <div className={`text-3xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'} group-hover:scale-110 transition-transform duration-300`}>{stat.number}</div>
                  <div className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>{stat.label}</div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Right Side - Visual */}
        <div className={`hidden lg:block lg:w-1/2 relative ${isDarkMode ? 'bg-gradient-to-br from-gray-800 to-gray-900' : 'bg-gradient-to-br from-blue-50 to-indigo-100'}`}>
          {/* Decorative Elements */}
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="relative">
              {/* Main Product Circle */}
              <div className={`w-80 h-80 rounded-full shadow-2xl flex items-center justify-center ${isDarkMode ? 'bg-gray-800' : 'bg-white'}`}>
                <div className="text-center space-y-4">
                  <div className="text-6xl">🥛</div>
                  <div className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Fresh Milk</div>
                  <div className={isDarkMode ? 'text-gray-400' : 'text-gray-600'}>Daily Delivery</div>
                </div>
              </div>
              
              {/* Floating Products */}
              <div className={`absolute -top-10 -right-10 w-20 h-20 rounded-full flex items-center justify-center shadow-lg ${isDarkMode ? 'bg-gray-700' : 'bg-yellow-100'}`}>
                <span className="text-2xl">🧀</span>
              </div>
              
              <div className={`absolute -bottom-10 -left-10 w-20 h-20 rounded-full flex items-center justify-center shadow-lg ${isDarkMode ? 'bg-gray-700' : 'bg-orange-100'}`}>
                <span className="text-2xl">🧈</span>
              </div>
              
              <div className={`absolute top-1/2 -right-16 w-16 h-16 rounded-full flex items-center justify-center shadow-lg ${isDarkMode ? 'bg-gray-700' : 'bg-green-100'}`}>
                <span className="text-xl">🌿</span>
              </div>
            </div>
          </div>
          
          {/* Background Pattern */}
          <div className="absolute inset-0 opacity-10">
            <div className={`absolute top-10 right-10 w-32 h-32 border-2 rounded-full ${isDarkMode ? 'border-gray-600' : 'border-blue-300'}`}></div>
            <div className={`absolute bottom-20 left-20 w-24 h-24 border-2 rounded-full ${isDarkMode ? 'border-gray-600' : 'border-indigo-300'}`}></div>
            <div className={`absolute top-1/3 left-1/4 w-16 h-16 border-2 rounded-full ${isDarkMode ? 'border-gray-600' : 'border-purple-300'}`}></div>
          </div>
        </div>
      </section>



      
      {/* Modern Categories Section */}



      <section className="mb-16 relative">



        {/* Modern Section Header */}



        <div className="text-center mb-12">



          <div className="inline-block relative group">



            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>



              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">



                Shop by Category



              </span>



            </h2>



            {/* Animated Underline - Like Featured Products */}



            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>



          </div>



          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>



            Explore our wide range of fresh dairy products



          </p>



        </div>







        {/* Modern Grid Layout */}



        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-8">



          {categories.map((category) => (



            <Link



              key={category}



              to={`/products?category=${category}`}



              className="group relative block"



            >



              {/* Ultra-Premium Card Container */}



              <div className="relative p-10 text-center bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black rounded-[3rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500 transition-all duration-1000 transform hover:scale-105 hover:shadow-4xl hover:shadow-primary-500/20 overflow-hidden group">



                



                {/* Multi-Layer Animated Background */}



